// Encabezado para PDFs armados con jsPDF: logo a la izquierda, datos del negocio al lado, tipo/número a la derecha y una línea fina. Ocupa de y=10 a y=33.
const dibujarEncabezadoPdfDoc = (doc, { logo = '', empresa = '', lineasEmpresa = [], tipo = '', numero = '', lineasDoc = [], reglaY = 33 } = {}) => {
  const pageW = doc.internal.pageSize.getWidth();
  const x0 = 14;
  const x1 = pageW - 14;
  const top = 10;
  let textoX = x0;
  doc.setFillColor(255, 255, 255);
  if (logo) {
    try {
      const props = doc.getImageProperties(logo);
      const ratio = (props?.width || 1) / Math.max(props?.height || 1, 1);
      let w = 46;
      let h = w / Math.max(ratio, 0.01);
      if (h > 17) { h = 17; w = h * ratio; }
      doc.addImage(logo, /image\/jpe?g/i.test(logo) ? 'JPEG' : 'PNG', x0, top + (17 - h) / 2, w, h);
      textoX = x0 + Math.max(w, 30) + 6;
    } catch (error) { /* logo opcional */ }
  }
  doc.setTextColor(17, 24, 39);
  if (!logo || textoX === x0) {
    doc.setFont('helvetica', 'bold'); doc.setFontSize(15);
    doc.text(String(empresa || 'MI NEGOCIO').toUpperCase(), x0, top + 6, { maxWidth: (x1 - x0) * 0.5 });
    textoX = x0;
  }
  doc.setFont('helvetica', 'normal'); doc.setFontSize(7.6); doc.setTextColor(55, 65, 81);
  const anchoTexto = Math.max(40, (x1 - 62) - textoX);
  const lineas = lineasEmpresa.filter(Boolean).flatMap((linea) => doc.splitTextToSize(String(linea), anchoTexto)).slice(0, 4);
  const yLineas = (!logo || textoX === x0) ? top + 11 : top + 3.5;
  lineas.forEach((linea, i) => doc.text(linea, textoX, yLineas + i * 3.6));
  doc.setFont('helvetica', 'bold'); doc.setFontSize(8); doc.setTextColor(75, 85, 99);
  doc.text(String(tipo || '').toUpperCase(), x1, top + 3, { align: 'right' });
  doc.setFontSize(14); doc.setTextColor(17, 24, 39);
  doc.text(String(numero || ''), x1, top + 10, { align: 'right', maxWidth: 62 });
  doc.setFont('helvetica', 'normal'); doc.setFontSize(7.6); doc.setTextColor(55, 65, 81);
  lineasDoc.filter(Boolean).slice(0, 3).forEach((linea, i) => doc.text(String(linea), x1, top + 15 + i * 3.6, { align: 'right', maxWidth: 62 }));
  doc.setDrawColor(17, 24, 39); doc.setLineWidth(0.5);
  doc.line(x0, reglaY, x1, reglaY);
  doc.setLineWidth(0.2);
  doc.setTextColor(15, 23, 42);
};
