const OPCIONES_FACTURA_CUENTA_CORRIENTE = [
  { value: 'factura_a', label: 'Factura A' },
  { value: 'factura_b', label: 'Factura B' }
];
const obtenerEtiquetaFactura = (tipo = 'factura_b') => (
  OPCIONES_FACTURA_CUENTA_CORRIENTE.find((op) => op.value === tipo)?.label || 'Factura B'
);
const normalizarReferenciaFacturaExterna = (detalles = {}) => {
  const factura = detalles?.facturaExterna || detalles?.recibo?.facturaExterna || {};
  const tipo = textoSeguroTrim(
    factura?.tipo,
    textoSeguroTrim(detalles?.facturaExternaTipo, textoSeguroTrim(detalles?.recibo?.facturaExternaTipo, ''))
  );
  const numero = textoSeguroTrim(
    factura?.numero,
    textoSeguroTrim(detalles?.facturaExternaNumero, textoSeguroTrim(detalles?.recibo?.facturaExternaNumero, ''))
  );
  if (!tipo || !numero) return null;
  const etiqueta = obtenerEtiquetaFactura(tipo);
  return {
    tipo,
    numero,
    etiqueta,
    texto: `${etiqueta} N° ${numero}`
  };
};
const obtenerTipoFacturaSugeridaCliente = (cliente = null) => {
  const condicion = normalizarTextoBusqueda(
    cliente?.condicionFiscal
    || cliente?.condicionIva
    || cliente?.condicion_iva
    || cliente?.situacionFiscal
    || cliente?.iva
    || ''
  );
  if (!condicion) return 'factura_b';
  if (
    condicion.includes('responsable')
    || condicion.includes('inscrip')
    || condicion.includes('ri')
    || condicion.includes('responsable inscripto')
  ) {
    return 'factura_a';
  }
  return 'factura_b';
};
const textoCondicionFiscalCliente = (cliente = null) => {
  const condicion = textoSeguroTrim(
    cliente?.condicionFiscal
    || cliente?.condicionIva
    || cliente?.condicion_iva
    || cliente?.situacionFiscal
    || cliente?.iva,
    ''
  );
  return condicion || 'Sin condición fiscal';
};
