const formatearTextoDias = (dias = 0) => {
  const n = Math.max(0, Number.isFinite(Number(dias)) ? Number(dias) : 0);
  return `${n} día${n === 1 ? '' : 's'}`;
};
const descargarCsvSimple = (nombre, filas) => {
  const esc = (v) => { const t = String(v ?? ''); return /[;"\n]/.test(t) ? `"${t.replace(/"/g, '""')}"` : t; };
  const blob = new Blob([`\uFEFF${filas.map((f) => f.map(esc).join(';')).join('\n')}`], { type: 'text/csv;charset=utf-8;' });
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url; a.download = nombre;
  document.body.appendChild(a); a.click(); document.body.removeChild(a);
  setTimeout(() => URL.revokeObjectURL(url), 1000);
};
