const limpiarDatoFirestore = (valor) => {
  if (valor === undefined) return null;
  if (Array.isArray(valor)) return valor.map((item) => limpiarDatoFirestore(item)).filter((item) => item !== undefined);
  if (valor && typeof valor === 'object' && !(valor instanceof Date)) {
    return Object.entries(valor).reduce((acc, [clave, item]) => {
      if (item !== undefined) acc[clave] = limpiarDatoFirestore(item);
      return acc;
    }, {});
  }
  return valor;
};
const promesaConTimeout = (promesa, timeoutMs = 15000, mensaje = 'La operación tardó demasiado.') => (
  Promise.race([
    promesa,
    new Promise((_, reject) => {
      setTimeout(() => reject(new Error(mensaje)), timeoutMs);
    })
  ])
);
const esDataUrlPesada = (valor = '') => textoSeguroTrim(valor, '').startsWith('data:');
const MS_POR_DIA = 1000 * 60 * 60 * 24;
const calcularPlazoEntreFechas = (fechaEmision = '', fechaCobro = '') => {
  if (!fechaEmision || !fechaCobro) return '';
  const inicio = new Date(`${fechaEmision}T12:00:00`);
  const fin = new Date(`${fechaCobro}T12:00:00`);
  if (Number.isNaN(inicio.getTime()) || Number.isNaN(fin.getTime())) return '';
  return String(Math.max(0, Math.round((fin.getTime() - inicio.getTime()) / MS_POR_DIA)));
};
