const obtenerFechaInputLocal = (fecha = new Date()) => {
  const d = fecha instanceof Date ? fecha : new Date(fecha);
  const ajuste = d.getTime() - (d.getTimezoneOffset() * 60000);
  return new Date(ajuste).toISOString().slice(0, 10);
};

const esFechaInputValida = (valor = '') => /^\d{4}-\d{2}-\d{2}$/.test((valor || '').toString().trim());

const sumarDiasFechaInputLocal = (fechaInput = '', dias = 0) => {
  const base = esFechaInputValida(fechaInput)
    ? new Date(`${fechaInput}T12:00:00`)
    : new Date();
  if (Number.isNaN(base.getTime())) return obtenerFechaInputLocal();
  base.setDate(base.getDate() + (Number.isFinite(Number(dias)) ? Number(dias) : 0));
  return obtenerFechaInputLocal(base);
};

const obtenerRangoVigenciaOfertaDefault = () => {
  const desde = obtenerFechaInputLocal();
  return {
    desde,
    hasta: sumarDiasFechaInputLocal(desde, 7)
  };
};

const esPlanTarjetaVigenteEnFecha = (plan = {}, fechaReferencia = obtenerFechaInputLocal()) => {
  const normalizado = normalizarPlanTarjeta(plan);
  if (!normalizado.vigenciaActiva) return true;
  const hoy = esFechaInputValida(fechaReferencia) ? fechaReferencia : obtenerFechaInputLocal();
  const desde = esFechaInputValida(normalizado.vigenciaDesde) ? normalizado.vigenciaDesde : '';
  const hasta = esFechaInputValida(normalizado.vigenciaHasta) ? normalizado.vigenciaHasta : '';
  if (desde && hoy < desde) return false;
  if (hasta && hoy > hasta) return false;
  return true;
};

const esPlanTarjetaPromoVigente = (plan = {}, fechaReferencia = obtenerFechaInputLocal()) => {
  const normalizado = normalizarPlanTarjeta(plan);
  return Boolean(normalizado.vigenciaActiva && esPlanTarjetaVigenteEnFecha(normalizado, fechaReferencia));
};

const formatearFechaInputLocal = (fechaInput = '') => {
  if (!esFechaInputValida(fechaInput)) return '';
  return formatearFecha(new Date(`${fechaInput}T12:00:00`));
};

const combinarFechaInputConHoraReferenciaISO = (fechaInput = '', referencia = null) => {
  if (!esFechaInputValida(fechaInput)) return new Date().toISOString();
  const fechaBase = new Date(`${fechaInput}T00:00:00`);
  if (Number.isNaN(fechaBase.getTime())) return new Date().toISOString();
  const ref = referencia ? new Date(referencia) : new Date();
  if (!Number.isNaN(ref.getTime())) {
    fechaBase.setHours(ref.getHours(), ref.getMinutes(), ref.getSeconds(), ref.getMilliseconds());
  }
  return fechaBase.toISOString();
};

