const obtenerPaginaLista = (items = [], pagina = 1, porPagina = 25) => {
  const total = items.length;
  const totalPaginas = Math.max(1, Math.ceil(total / porPagina));
  const paginaSegura = Math.min(Math.max(1, pagina), totalPaginas);
  const inicio = total ? (paginaSegura - 1) * porPagina : 0;
  return { items: items.slice(inicio, inicio + porPagina), total, totalPaginas, pagina: paginaSegura, inicio, fin: Math.min(inicio + porPagina, total) };
};

const SFPagination = ({ pagina, porPagina, total, entidad = 'registros', onPaginaChange, onPorPaginaChange }) => {
  const totalPaginas = Math.max(1, Math.ceil(total / porPagina));
  const paginaSegura = Math.min(Math.max(1, pagina), totalPaginas);
  const paginas = Array.from({ length: totalPaginas }, (_, index) => index + 1);
  const visibles = totalPaginas <= 7
    ? paginas
    : [...new Set([1, Math.max(1, paginaSegura - 1), paginaSegura, Math.min(totalPaginas, paginaSegura + 1), totalPaginas])].sort((a, b) => a - b);
  const inicio = total ? ((paginaSegura - 1) * porPagina) + 1 : 0;
  const fin = Math.min(paginaSegura * porPagina, total);
  return (
    <div className="sf-pagination shrink-0 flex flex-col gap-2 border-t border-slate-100 px-3 py-2.5 sm:flex-row sm:items-center sm:justify-between">
      <p className="text-[11px] font-semibold text-slate-500">Mostrando {inicio} a {fin} de {total} {entidad}</p>
      <div className="flex items-center justify-between gap-2 sm:justify-end">
        <div className="hidden items-center gap-1 sm:flex">
          <button type="button" onClick={() => onPaginaChange(paginaSegura - 1)} disabled={paginaSegura === 1} aria-label="Página anterior">‹</button>
          {visibles.map((numero, index) => <React.Fragment key={numero}>{index > 0 && numero - visibles[index - 1] > 1 && <span className="px-0.5 text-slate-400">…</span>}<button type="button" onClick={() => onPaginaChange(numero)} className={numero === paginaSegura ? 'sf-pagination-active' : ''}>{numero}</button></React.Fragment>)}
          <button type="button" onClick={() => onPaginaChange(paginaSegura + 1)} disabled={paginaSegura === totalPaginas} aria-label="Página siguiente">›</button>
        </div>
        <div className="flex items-center gap-1 sm:hidden">
          <button type="button" onClick={() => onPaginaChange(paginaSegura - 1)} disabled={paginaSegura === 1}>‹ Anterior</button>
          <span className="px-1 text-[10px] font-bold text-slate-500">Página {paginaSegura} de {totalPaginas}</span>
          <button type="button" onClick={() => onPaginaChange(paginaSegura + 1)} disabled={paginaSegura === totalPaginas}>Siguiente ›</button>
        </div>
        <select aria-label="Registros por página" value={porPagina} onChange={(event) => onPorPaginaChange(Number(event.target.value))} className="h-8 rounded-md border border-slate-200 bg-white px-2 text-[10px] font-bold text-slate-600 outline-none">
          {[25, 50, 100].map((cantidad) => <option key={cantidad} value={cantidad}>{cantidad} por página</option>)}
        </select>
      </div>
    </div>
  );
};

const obtenerPerfilPantalla = () => {
  if (typeof window === 'undefined') {
    return { ancho: 1024, alto: 768, tipo: 'desktop', orientacion: 'landscape', altura: 'normal', densidad: 'normal' };
  }
  const viewport = window.visualViewport || null;
  const ancho = Math.round(viewport?.width || window.innerWidth || document.documentElement?.clientWidth || 1024);
  const alto = Math.round(viewport?.height || window.innerHeight || document.documentElement?.clientHeight || 768);
  const tipo = ancho < 640 ? 'phone' : (ancho < 1024 ? 'tablet' : (ancho >= 1536 ? 'wide' : 'desktop'));
  const orientacion = ancho >= alto ? 'landscape' : 'portrait';
  const altura = alto < 620 ? 'short' : 'normal';
  const densidad = ancho < 390 || alto < 560 ? 'compact' : 'normal';
  return { ancho, alto, tipo, orientacion, altura, densidad };
};

const aplicarPerfilPantallaDocumento = (perfil) => {
  if (typeof document === 'undefined' || !perfil) return;
  const root = document.documentElement;
  root.dataset.sfScreen = perfil.tipo;
  root.dataset.sfOrientation = perfil.orientacion;
  root.dataset.sfHeight = perfil.altura;
  root.dataset.sfDensity = perfil.densidad;
  root.style.setProperty('--sf-vw', `${perfil.ancho}px`);
  root.style.setProperty('--sf-vh', `${perfil.alto}px`);
  // Pantallas grandes (Full HD, 2K, 4K): tamaño normal, con más espacio.
  // Pantallas chicas de escritorio (HD, notebooks): se achica un poco para que entre lo mismo sin pisarse.
  const factorAncho = perfil.ancho >= 1440 || perfil.ancho < 1024 ? 1 : Math.max(0.82, perfil.ancho / 1440);
  const factorAlto = perfil.ancho < 1024 || perfil.alto >= 800 ? 1 : Math.max(0.85, perfil.alto / 800);
  const factor = Math.round(Math.min(factorAncho, factorAlto) * 100) / 100;
  if (factor !== 1) {
    root.style.zoom = String(factor);
    root.style.setProperty('--sf-1vh', `${(perfil.alto / factor) / 100}px`);
    root.style.setProperty('--sf-1vw', `${(perfil.ancho / factor) / 100}px`);
  } else {
    root.style.removeProperty('zoom');
    root.style.removeProperty('--sf-1vh');
    root.style.removeProperty('--sf-1vw');
  }
  root.dataset.sfZoom = String(factor);
};

if (typeof window !== 'undefined' && !window.__sfZoomPrintHook) {
  window.__sfZoomPrintHook = true;
  let zoomPrevio = '';
  window.addEventListener('beforeprint', () => { zoomPrevio = document.documentElement.style.zoom || ''; document.documentElement.style.zoom = ''; });
  window.addEventListener('afterprint', () => { if (zoomPrevio) document.documentElement.style.zoom = zoomPrevio; });
}

const usarPerfilPantalla = () => {
  const [perfil, setPerfil] = useState(() => obtenerPerfilPantalla());

  useEffect(() => {
    // Un botón con ícono + texto + title no es un botón "solo ícono": se marca para que el CSS no lo achique.
    if (typeof document === 'undefined' || typeof MutationObserver === 'undefined') return undefined;
    let frame = 0;
    const marcar = () => {
      frame = 0;
      document.querySelectorAll('button[title]:not(.sf-has-text)').forEach((boton) => {
        if ((boton.textContent || '').trim()) boton.classList.add('sf-has-text');
      });
    };
    const observador = new MutationObserver(() => { if (!frame) frame = window.requestAnimationFrame(marcar); });
    observador.observe(document.body, { childList: true, subtree: true, characterData: true });
    marcar();
    return () => { observador.disconnect(); if (frame) window.cancelAnimationFrame(frame); };
  }, []);

  useEffect(() => {
    const actualizar = () => {
      const siguiente = obtenerPerfilPantalla();
      aplicarPerfilPantallaDocumento(siguiente);
      setPerfil((actual) => (
        actual.ancho === siguiente.ancho
        && actual.alto === siguiente.alto
        && actual.tipo === siguiente.tipo
        && actual.orientacion === siguiente.orientacion
        && actual.altura === siguiente.altura
        && actual.densidad === siguiente.densidad
          ? actual
          : siguiente
      ));
    };

    actualizar();
    window.addEventListener('resize', actualizar);
    window.addEventListener('orientationchange', actualizar);
    window.visualViewport?.addEventListener('resize', actualizar);
    window.visualViewport?.addEventListener('scroll', actualizar);

    return () => {
      window.removeEventListener('resize', actualizar);
      window.removeEventListener('orientationchange', actualizar);
      window.visualViewport?.removeEventListener('resize', actualizar);
      window.visualViewport?.removeEventListener('scroll', actualizar);
    };
  }, []);

  // Celular: cada tabla pasa a tarjetas; se copia el título de la columna a cada celda (data-label)
  const esCelular = perfil.ancho < 768;
  useEffect(() => {
    if (!esCelular || typeof document === 'undefined' || typeof MutationObserver === 'undefined') return undefined;
    let pendiente = 0;
    const etiquetar = () => {
      pendiente = 0;
      document.querySelectorAll('.sf-app-shell table').forEach((tabla) => {
        const cabeceras = Array.from(tabla.querySelectorAll('thead th')).map((th) => (th.textContent || '').trim());
        if (!cabeceras.length) return;
        tabla.querySelectorAll('tbody tr').forEach((fila) => {
          let col = 0;
          Array.from(fila.children).forEach((celda) => {
            if (celda.tagName !== 'TD') return;
            if (celda.dataset.label === undefined) celda.dataset.label = cabeceras[col] || '';
            col += celda.colSpan || 1;
          });
        });
      });
    };
    const programar = () => { if (!pendiente) pendiente = window.setTimeout(etiquetar, 60); };
    const observador = new MutationObserver(programar);
    observador.observe(document.body, { childList: true, subtree: true });
    programar();
    return () => { observador.disconnect(); if (pendiente) window.clearTimeout(pendiente); };
  }, [esCelular]);

  return perfil;
};

