    setOfertaVigenciaHasta(esFechaInputValida(oferta.vigenciaHasta) ? oferta.vigenciaHasta : (esFechaInputValida(oferta.vigenciaDesde) ? oferta.vigenciaDesde : rangoDefault.hasta));
