                            <button key={`mm-red-${o.k || 'no'}`} type="button" className={`sf-mm-chip ${modMasivaRedondeo === o.k ? 'is-on' : ''}`} onClick={() => setModMasivaRedondeo(o.k)}>{o.t}</button>
